/** Cria uma categoria do catálogo. parentId permite subcategorias (ferramentas, calçados...). */
export const createCategory = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input) =>
    z
      .object({
        organizationId: z.string().uuid(),
        name: z.string().trim().min(2).max(120),
        parentId: z.string().uuid().nullable().optional(),
      })
      .parse(input),
  )
  .handler(async ({ data, context }) => {
    await requireOrgPermission(
      context.supabase,
      data.organizationId,
      PERMISSIONS.productsManage,
      context.userId,
    );

    const { data: created, error } = await context.supabase
      .from("product_categories")
      .insert({
        organization_id: data.organizationId,
        name: data.name,
        parent_id: data.parentId ?? null,
        created_by: context.userId,
        updated_by: context.userId,
      })
      .select("id, name")
      .single();
    if (error) throw new Error(error.message);

    await context.supabase.from("audit_log").insert({
      organization_id: data.organizationId,
      user_id: context.userId,
      action: "category.create",
      resource: "product_categories",
      resource_id: created.id,
      context: { name: created.name },
    });

    return created;
  });

/** Renomeia/move uma categoria. */
export const updateCategory = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input) =>
    z
      .object({
        organizationId: z.string().uuid(),
        categoryId: z.string().uuid(),
        name: z.string().trim().min(2).max(120),
        parentId: z.string().uuid().nullable().optional(),
      })
      .parse(input),
  )
  .handler(async ({ data, context }) => {
    await requireOrgPermission(
      context.supabase,
      data.organizationId,
      PERMISSIONS.productsManage,
      context.userId,
    );

    const { error } = await context.supabase
      .from("product_categories")
      .update({ name: data.name, parent_id: data.parentId ?? null, updated_by: context.userId })
      .eq("id", data.categoryId)
      .eq("organization_id", data.organizationId);
    if (error) throw new Error(error.message);

    await context.supabase.from("audit_log").insert({
      organization_id: data.organizationId,
      user_id: context.userId,
      action: "category.update",
      resource: "product_categories",
      resource_id: data.categoryId,
      context: { name: data.name },
    });

    return { ok: true };
  });

/** Remove uma categoria que não esteja em uso por nenhum produto. */
export const deleteCategory = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input) =>
    z.object({ organizationId: z.string().uuid(), categoryId: z.string().uuid() }).parse(input),
  )
  .handler(async ({ data, context }) => {
    await requireOrgPermission(
      context.supabase,
      data.organizationId,
      PERMISSIONS.productsManage,
      context.userId,
    );

    const { data: refs, error: refsError } = await context.supabase
      .from("products")
      .select("id")
      .eq("category_id", data.categoryId)
      .eq("organization_id", data.organizationId)
      .limit(1);
    if (refsError) throw new Error(refsError.message);
    if (refs?.length) {
      throw new Error("Esta categoria possui produtos vinculados. Reatribua-os antes de excluir.");
    }

    const { error } = await context.supabase
      .from("product_categories")
      .delete()
      .eq("id", data.categoryId)
      .eq("organization_id", data.organizationId);
    if (error) throw new Error(error.message);

    await context.supabase.from("audit_log").insert({
      organization_id: data.organizationId,
      user_id: context.userId,
      action: "category.delete",
      resource: "product_categories",
      resource_id: data.categoryId,
    });

    return { ok: true };
  });

await context.supabase.from("audit_log").insert({
      organization_id: data.organizationId,
      user_id: context.userId,
      action: "category.delete",
      resource: "product_categories",
      resource_id: data.categoryId,
    });

    return { ok: true };
  });

/** Cria uma variante comercial (SKU) vinculada ao produto. */
export const createVariant = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator((input) =>
    z
      .object({
        organizationId: z.string().uuid(),
        productId: z.string().uuid(),
        sku: z.string().trim().min(1).max(40),
        barcode: z.string().trim().max(64).nullable().optional(),
        size: z.string().trim().max(40).nullable().optional(),
        color: z.string().trim().max(60).nullable().optional(),
        costPrice: priceSchema,
        sellPrice: priceSchema,
        weightGrams: weightSchema,
        status: variantStatusSchema.default("ACTIVE"),
      })
      .parse(input),
  )
  .handler(async ({ data, context }) => {
    await requireOrgPermission(
      context.supabase,
      data.organizationId,
      PERMISSIONS.productsManage,
      context.userId,
    );

    const { data: created, error } = await context.supabase
      .from("product_variants")
      .insert({
        organization_id: data.organizationId,
        product_id: data.productId,
        sku: data.sku,
        barcode: emptyToNull(data.barcode),
        size: emptyToNull(data.size),
        color: emptyToNull(data.color),
        cost_price: data.costPrice ?? null,
        sell_price: data.sellPrice ?? null,
        weight_grams: data.weightGrams ?? null,
        status: data.status,
        created_by: context.userId,
        updated_by: context.userId,
      })
      .select("id, sku, status")
      .single();
    if (error) throw new Error(error.message);

    await context.supabase.from("audit_log").insert({
      organization_id: data.organizationId,
      user_id: context.userId,
      action: "variant.create",
      resource: "product_variants",
      resource_id: created.id,
      context: { product_id: data.productId, sku: created.sku },
    });

    return created;
  });

/** Atualiza os dados de uma variante existente. */
